import json,hashlib
from ops import remote,M7,T3,session,B,BASE,P
r=remote(M7,'''import os,sys,json,subprocess
os.chdir('/opt/constellation/metadata-engine-runtime');sys.path.insert(0,os.getcwd())
from metadata_engine.runtime_db import Database
db=Database(json.load(open('config/metadata-engine.json')))
print(json.dumps({'publication_rotation':db.cursor('reviewed-publication-rotation'),'failed_services':subprocess.run(['systemctl','list-units','--failed','optima-*','constellation-*','--no-pager','--no-legend'],capture_output=True,text=True).stdout,'publication_unit':subprocess.run(['systemctl','show','optima-m7-aux-reviewed-metadata-publication.service','-p','ActiveState','-p','Result','-p','ExecMainStatus'],capture_output=True,text=True).stdout}))
''');(P/'final-m7-service-check.json').write_text(r['out']);print('m7',r['out'],flush=True)
r=remote(T3,"import subprocess,json;print(json.dumps({'failed_services':subprocess.run(['systemctl','list-units','--failed','optima-*','constellation-*','--no-pager','--no-legend'],capture_output=True,text=True).stdout}))");(P/'final-t3-service-check.json').write_text(r['out']);print('t3',r['out'],flush=True)
report=json.loads((P/'review-complete.json').read_text());report['final_service_checks']={h:json.loads((P/('final-'+h+'-service-check.json')).read_text())for h in ['m7','t3']};assert all(not d['failed_services'].strip()for d in report['final_service_checks'].values());report['additional_market_recovery']=json.loads((P/'market-service-recovery.json').read_text());rollout_path=P/'preventive-service-role-rollout-receipt.json';rollout=json.loads(rollout_path.read_text())if rollout_path.exists()else None;report['optional_preventive_credentials']=({'status':rollout['status'],'owner_approved':True,'services_approved':44,'installed':len(rollout['installed']),'already_installed':len(rollout['already_installed']),'skipped':rollout['skipped'],'verified':len(rollout['verification']),'restarts':[],'receipt':rollout_path.name,'applied_at':rollout['finished_at'],'activation_note':rollout['activation_note']}if rollout else {'status':'awaiting_owner_approval; not applied','prepared_plan':'preventive-service-role-plan.json','services':44});(P/'review-complete.json').write_text(json.dumps(report,indent=2,default=str)+'\n')
names=['review-complete.json','raw-s3-locators.json','review-queries.sql','final-tests.log','counts-final.json','counts-final-first.json','unido-measurements-final.json','portwatch-dates-final.json','after.json','source-lanes.json','other-raw-validation.json','statistics-capture.json','economic-validation.json','sam-validation.json','exact-final-publications.json','copernicus-metadata-recovery.json','final-m7-service-check.json','final-t3-service-check.json','worker-check-after-m7.json','worker-check-after-t3.json','market-failure.json','market-service-role-repair.json','market-service-recovery.json','preventive-service-role-plan.json']
s=session.client('s3');manifest={}
for name in names:
 raw=(P/name).read_bytes();s.put_object(Bucket=B,Key=BASE+name,Body=raw,ServerSideEncryption='AES256');manifest[name]={'sha256':hashlib.sha256(raw).hexdigest(),'bytes':len(raw)}
s.put_object(Bucket=B,Key=BASE+'review-artifact-manifest.json',Body=json.dumps(manifest,indent=2).encode(),ServerSideEncryption='AES256');(P/'review-artifact-manifest.json').write_text(json.dumps(manifest,indent=2)+'\n')
body=s.get_object(Bucket=B,Key=BASE+'review-complete.json')['Body'].read();assert hashlib.sha256(body).hexdigest()==manifest['review-complete.json']['sha256'];print('Saved and read back',len(names),'review artifacts with checksums.',flush=True)
